using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Tilemaps;public static class InspectMinePath{public static object Main(){var rows=new List<object>();foreach(var m in GameObject.Find("Hometown").GetComponentsInChildren<Tilemap>(true).Where(m=>m.name.Contains("Path")))foreach(var p in m.cellBounds.allPositionsWithin){if(!m.HasTile(p))continue;var w=m.GetCellCenterWorld(p);if(w.x> -68&&w.x< -57&&w.y>6&&w.y<15)rows.Add(new{map=m.name,x=p.x,y=p.y,wx=w.x,wy=w.y,tile=m.GetTile(p).name});}return rows.ToArray();}}
